<?php require '../includes/auth.php';require_role('seller');$sid=seller_profile_id(user()['id']);$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$pdo->prepare('UPDATE seller_profiles SET shop_name=?,description=?,location=? WHERE id=?')->execute([post('shop_name'),post('description'),post('location'),$sid]);flash('success','Shop profile updated.');redirect('seller/profile.php');}$s=$pdo->prepare('SELECT * FROM seller_profiles WHERE id=?');$s->execute([$sid]);$p=$s->fetch();$pageTitle='Shop profile';require '../includes/header.php';?><div class="page-title"><p class="eyebrow">SELLER SETTINGS</p><h1>Shop profile</h1></div><form class="card-form narrow" method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><p>Approval: <span class="badge <?=status_class($p['approval_status'])?>"><?=e($p['approval_status'])?></span></p><label>Shop name<input name="shop_name" value="<?=e($p['shop_name'])?>" required></label><label>Location<input name="location" value="<?=e($p['location'])?>"></label><label>About your shop<textarea name="description"><?=e($p['description'])?></textarea></label><button>Save profile</button></form><?php require '../includes/footer.php'; ?>
